<template>
  <div class="container">
    <h1>YOLO目标检测</h1>
    
    <div class="upload-section">
      <form @submit.prevent="handleSubmit">
        <input 
          type="file" 
          id="imageInput" 
          name="image" 
          accept="image/*" 
          required
          @change="handleImageChange"
        >
        <button type="submit" class="button">上传并检测</button>
      </form>
      
      <div v-if="imagePreviewUrl" class="image-preview-container">
        <img 
          :src="imagePreviewUrl" 
          alt="预览图" 
          class="image-preview"
        >
      </div>
    </div>

    <div class="results-section">
      <h3>检测结果</h3>
      <div id="detectionResults">
        <div v-if="isLoading" class="loading">
          <p>正在检测中...</p>
        </div>
        
        <div v-if="errorMessage" class="error">
          {{ errorMessage }}
        </div>
        
        <div v-if="detections.length > 0 && !isLoading && !errorMessage">
          <p>检测到 {{ detections.length }} 个对象：</p>
          <ul>
            <li v-for="(obj, index) in detections" :key="index">
              {{ obj.class }} (置信度：{{ obj.confidence.toFixed(2) }})，位置：{{ formatBox(obj.box) }}
            </li>
          </ul>
        </div>
        
        <div v-if="detections.length === 0 && !isLoading && !errorMessage && hasResults">
          <p>未检测到对象</p>
        </div>
      </div>
      
      <img 
        v-if="annotatedImageUrl && !isLoading && !errorMessage" 
        :src="annotatedImageUrl" 
        class="result-image" 
        alt="检测结果图片"
      >
    </div>
  </div>
</template>

<script setup>
import { ref } from 'vue';

// 状态管理
const imageFile = ref(null);
const imagePreviewUrl = ref('');
const detections = ref([]);
const annotatedImageUrl = ref('');
const isLoading = ref(false);
const errorMessage = ref('');
const hasResults = ref(false);

// 处理图片选择
const handleImageChange = (e) => {
  const file = e.target.files[0];
  if (file) {
    imageFile.value = file;
    // 生成预览图
    const reader = new FileReader();
    reader.onload = (event) => {
      imagePreviewUrl.value = event.target.result;
    };
    reader.readAsDataURL(file);
  }
};

// 格式化边界框显示
const formatBox = (box) => {
  return box.map(coord => coord.toFixed(2)).join(', ');
};

// 处理表单提交
const handleSubmit = async () => {
  if (!imageFile.value) return;
  
  // 重置状态
  isLoading.value = true;
  errorMessage.value = '';
  detections.value = [];
  annotatedImageUrl.value = '';
  hasResults.value = false;
  
  try {
    const formData = new FormData();
    formData.append('image', imageFile.value);
    
    const response = await fetch('https://123.56.203.202/detect', {
      method: 'POST',
      body: formData
    });

    if (!response.ok) {
      throw new Error(`HTTP错误！状态码：${response.status}`);
    }

    const data = await response.json();
    
    if (data.error) {
      throw new Error(data.error);
    }
    
    // 更新状态
    hasResults.value = true;
    detections.value = data.detections || [];
    
    // 显示标注后的图片
    if (data.annotated_image) {
      annotatedImageUrl.value = `data:image/jpg;base64,${data.annotated_image}`;
    }

  } catch (error) {
    errorMessage.value = `错误：${error.message}`;
    console.error('检测失败：', error);
  } finally {
    isLoading.value = false;
  }
};
</script>

<style scoped>
.container {
  font-family: Arial, sans-serif;
  max-width: 800px;
  margin: 0 auto;
  padding: 20px;
  background-color: #f5f5f5;
  border-radius: 8px;
}

.upload-section {
  margin-bottom: 20px;
}

.image-preview-container {
  margin: 10px 0;
}

.image-preview {
  max-width: 100%;
  height: auto;
  border: 1px solid #ddd;
  border-radius: 4px;
}

.results-section {
  margin-top: 20px;
}

.result-image {
  max-width: 100%;
  margin-top: 10px;
  border-radius: 4px;
  box-shadow: 0 0 10px rgba(0,0,0,0.1);
}

.button {
  background-color: #4CAF50;
  border: none;
  color: white;
  padding: 8px 16px;
  text-align: center;
  text-decoration: none;
  display: inline-block;
  font-size: 14px;
  margin: 4px 2px;
  cursor: pointer;
  border-radius: 4px;
}

.button:disabled {
  background-color: #cccccc;
  cursor: not-allowed;
}

.error {
  color: red;
  margin-top: 10px;
}

.loading {
  color: #666;
  margin-top: 10px;
}

ul {
  list-style-type: none;
  padding: 0;
}

ul li {
  margin: 5px 0;
  padding: 5px;
  background-color: #f0f0f0;
  border-radius: 4px;
}
</style>
